ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(safeboot|bootstatuspolicy\s+ignoreallfailures|recoveryenabled\s+no)/i)
  OR (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete\s+shadows/i)
  OR (ImageFileName=/\\wmic\.exe$/i AND CommandLine=/shadowcopy\s+delete/i)
  OR (ImageFileName=/\\wbadmin\.exe$/i AND CommandLine=/delete\s+(catalog|backup|systemstatebackup)/i)
  OR (ImageFileName=/\\(net1?|sc|taskkill)\.exe$/i AND CommandLine=/(veeam|mssql|sqlserver|msexchange|backup|acronis|sophos|sentinel|defender)/i)
| case {
    ImageFileName=/bcdedit/i | Activity := "safeboot_bcd" ;
    ImageFileName=/(vssadmin|wmic)/i | Activity := "shadow_wipe" ;
    ImageFileName=/wbadmin/i | Activity := "backup_wipe" ;
    * | Activity := "service_stop"
  }
| Bucket := time:format(@timestamp, format="%Y-%m-%d %H:%M", granularity=10m)
| groupBy([aid, ComputerName, Bucket], function=[count(field=Activity, distinct=true, as=DistinctActivities), collect([Activity, CommandLine, ImageFileName, UserName])])
| DistinctActivities >= 3
| sort(Bucket, order=desc)
